call kg_assert_env('98');

-- Immutable merchant consent; templates remain editable through system notice management.
create table if not exists kg_merchant_agreement_consent (
 id bigint not null auto_increment,
 store_id bigint not null,
 app_user_id bigint not null,
 business_type varchar(24) not null,
 doc_version char(64) not null,
 title varchar(100) not null,
 content_html mediumtext not null,
 store_name varchar(128) not null default '',
 operator_name varchar(64) not null default '',
 confirmed_at datetime not null,
 primary key(id),
 unique key uk_merchant_consent(store_id,app_user_id,business_type,doc_version),
 key idx_merchant_consent_store(store_id,confirmed_at)
) engine=InnoDB;
call kg_assert_same_collation('kg_merchant_agreement_consent');
